/// <summary>
/// MPJ_28778 Item coverage
/// </summary>
[ExtensionOf(tableStr(ReqItemTable))]
final class METReqItemTable_Extension
{

}

Method.Source:
/// <summary>
/// Get the ReqItemTable extension
/// </summary>
/// <returns><c>METReqItemTable</c></returns>
public METReqItemTable metReqItemTable()
{
    return this.SysExtensionSerializerMap::getExtensionTable(tableNum(METReqItemTable));
}

    /// <summary>
    /// pack the <c>METReqItemTable</c>
    /// </summary>
    /// <param name = "_metReqItemTable"><c>METReqItemTable</c></param>
    public void metPackMETReqItemTable(METReqItemTable  _metReqItemTable)
    {
        _metReqItemTable.RefRecId = this.RecId;

        this.SysExtensionSerializerMap::packExtensionTable(_metReqItemTable);
    }

/// <summary>
///    Inserts a table buffer into the database.
/// </summary>
public void insert()
{        
    next insert();
    
    this.SysExtensionSerializerMap::postInsert();         
}

/// <summary>
///    Updates a table buffer into the database.
/// </summary>
public void update()
{
    next update();
    
    this.SysExtensionSerializerMap::postUpdate();        
}

    /// <summary>
    /// Method to retrieve <c>ReqItemTable</c> record
    /// </summary>
    /// <param name = "_itemId">Unique Item Id</param>
    /// <param name = "_covInventDimId">Inventory DimensionId</param>
    /// <param name = "_reqPOType">Order type</param>
    /// <returns><c>ReqItemTable</c> table buffer</returns>
    public static ReqItemTable metFindReqItemTable(ItemId _itemId, ReqCovInventDimId _covInventDimId, ReqPOType _reqPOType)
    {
        ReqItemTable reqItemTable;

        if (_itemId && _covInventDimId)
        {
            select firstonly reqItemTable
                where reqItemTable.ItemId == _itemId
                    && reqItemTable.CovInventDimId == _covInventDimId
                    && reqItemTable.ReqPOType == _reqPOType;

            if (!reqItemTable.RecId)
            {
                InventDim inventDim;
                InventDim inventDimSiteLocation = InventDim::find(_covInventDimId);

                inventDim.InventLocationId = inventDimSiteLocation.InventLocationId;
                inventDim.InventSiteId = inventDimSiteLocation.InventSiteId;

                InventDim inventDimFoundWithSiteLocation = InventDim::findOrCreate(inventDim);

                select firstonly reqItemTable
                    where reqItemTable.ItemId == _itemId
                        && reqItemTable.CovInventDimId == inventDimFoundWithSiteLocation.InventDimId
                        && reqItemTable.ReqPOType == _reqPOType;
            }
        }

        return reqItemTable;
    }

    /// <summary>
    /// Validate write
    /// </summary>
    /// <returns>true or false</returns>
    public boolean validateWrite()
    {
        boolean ret = next validateWrite();
        
        if (ret && this.METInterCompanySourced && ! this.METIntercompanySourcedWarehouse)
        {
            ret = checkFailed("@MET:IntercompanySourcedWarehouseValidation");
        }        

        return ret;
    }
